      visual: { kind: 'plot', title: 'Coulomb force vs distance (2.0 μC and 4.0 μC)', x: [0.1, 0.6], y: [0, 7.5], xLabel: 'r (m)', yLabel: 'F (N)', xticks: [0.1, 0.2, 0.3, 0.6], yticks: [0, 1.8, 7.2], series: [{ fn: '8.99e9*8e-12/(x*x)', color: 'gold', label: 'F ∝ 1/r²', lx: 0.58, ly: 1.2 }], notes: [[0.2, 2.6, '0.2 m → 1.8 N'], [0.36, 1.2, '0.3 m → 0.80 N']] },
      investigate: 'In the Electric Field Explorer, place two point charges and read the force meter as you change their separation from 10 cm to 20 cm to 40 cm. Plot F against 1/r² and check that the graph is a straight line through the origin.',
      mastery: ['I calculate Coulomb forces with correct SI units.', 'I predict force changes from charge and distance ratios.', 'I state the direction of the force and apply Newton’s third law.'],
      honors: {
        prompt: 'Charges +2.0 μC at x = 0, −3.0 μC at x = 0.10 m, and +4.0 μC at x = 0.25 m lie on a line. Find the net force on the −3.0 μC charge.',
        solution: 'From +2.0 μC (0.10 m away, attraction toward −x): F = k(6.0 × 10⁻¹²)/0.010 = 5.39 N. From +4.0 μC (0.15 m away, attraction toward +x): F = k(1.2 × 10⁻¹¹)/0.0225 = 4.79 N. Net = 5.39 − 4.79 = 0.60 N toward −x.',
        calc: ['P.coulomb(2.0e-6, 3.0e-6, 0.10) - P.coulomb(4.0e-6, 3.0e-6, 0.15)'], answers: [0.5991],
      },
      explainKeys: ['force is proportional to the product of the charges', 'force falls off as one over r squared', 'the two charges feel equal and opposite forces'],
